import AppError from "../../ErrorHandler/appErrors.js"
import { UserStatus } from "../User/user.interface.js"
import { User } from "../User/user.model.js"
import httpStatus from "http-status"
import bcrypt from "bcryptjs";
import { generateToken } from "../../utils/jwt.js";
import { envVars } from "../../confic/env.js";


export const credentialsLogin = async(payload: {email: string, password: string})=>{
    
    console.log("payload", payload)
    const user = await User.findOne({ email: payload.email, status:UserStatus.ACTIVE})
    if(!user){
        throw new AppError(httpStatus.BAD_REQUEST, "email is incorrect")
    }
   
    console.log("user",user)
    const isMatchPass = await bcrypt.compare(payload.password, user.password as string)

    if(!isMatchPass){
        throw new AppError(httpStatus.BAD_REQUEST, "password is incorrect")
    }

    const payloadJwt = {
        email: user.email as string,
        role: user.role
    }
    const accessToken = generateToken(payloadJwt, envVars.secret as string, envVars.expiresIn as string)
    const refreshToken = generateToken(payloadJwt, envVars.refresh_secret as string, envVars.refresh_expiresIn as string)
    return {
        accessToken,
        refreshToken,
        user: user
    }
}